import React, { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, BlurMask, LinearGradient, Path, RoundedRect, Skia, vec } from "@shopify/react-native-skia";
import Animated, {
  interpolateColor, runOnJS, useAnimatedStyle, useDerivedValue, useFrameCallback, useSharedValue,
} from "react-native-reanimated";
import {
  WHEEL_COLS, WHEEL_CY, WHEEL_H, WHEEL_SETTLE, WHEEL_SIZES, WHEEL_SLOW, WHEEL_W,
  drumTicks, rowGeom, rowLabel, rowOffset, wheelCreate, wheelFling, wheelGrab, wheelRelease, wheelSettled, wheelStep, wheelValue,
  type WheelState,
} from "./wheelMath";
import {
  WHEEL_ACCENT, WHEEL_BAND, WHEEL_BAND_H, WHEEL_BAND_W, WHEEL_BAND_X, WHEEL_COLON_X, WHEEL_DRUM_MID, WHEEL_DRUM_TOP,
  WHEEL_FONT_SIZE, WHEEL_INK_DIM, WHEEL_INK_LIT, WHEEL_SHEET, WHEEL_SHEET_EDGE, WHEEL_TITLE, WHEEL_TITLE_Y,
} from "./wheelDesign";

export type WheelTime = { hour: number; minute: number; period: "AM" | "PM" };
export type WheelTimePickerHandle = { spinDemo: () => void; reset: () => void };
export type WheelTimePickerProps = {
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onChange?: (time: WheelTime) => void;
  onFeedback?: (event: "tick" | "settle") => void;
  label?: string;
  style?: ViewStyle;
};

type Ptr = { d: number; kind: number; dy: number; vy: number; seq: number };
type Shared = { value: WheelState };

// Android stops presenting a canvas whose only change is internal on an idle
// screen. A 1 px layout change every frame keeps it drawing.
function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return <View pointerEvents="none" style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }} />;
}

function Row({ st, frame, d, i }: { st: Shared; frame: { value: number }; d: number; i: number }) {
  const style = useAnimatedStyle(() => {
    frame.value;
    const m = st.value.drums[d];
    const g = rowGeom(rowOffset(m, d, i), Math.abs(m.v));
    if (!g.visible) return { opacity: 0 };
    return {
      opacity: g.a * (1 - g.blur / 9),
      color: interpolateColor(g.lit, [0, 1], [WHEEL_INK_DIM, WHEEL_INK_LIT]),
      textShadowColor: g.lit > 0.5 ? WHEEL_ACCENT : WHEEL_INK_DIM,
      textShadowRadius: g.blur * 1.6 + g.lit * 3,
      transform: [{ translateY: g.y - WHEEL_CY }, { scaleY: Math.max(0.02, g.s) }, { scaleX: 0.92 + 0.08 * g.s }],
    };
  });
  return (
    <Animated.Text
      pointerEvents="none"
      style={[{
        position: "absolute", left: WHEEL_COLS[d] - 40, top: WHEEL_CY - 22, width: 80, height: 44, textAlign: "center",
        fontSize: WHEEL_FONT_SIZE, fontWeight: "500", lineHeight: 44, includeFontPadding: false, opacity: 0,
        color: WHEEL_INK_DIM, textShadowOffset: { width: 0, height: 0 },
      }, style]}
    >
      {rowLabel(d, i)}
    </Animated.Text>
  );
}

function Ticks({ st, frame, d }: { st: Shared; frame: { value: number }; d: number }) {
  const model = useDerivedValue(() => {
    frame.value;
    const m = st.value.drums[d];
    const { ticks, blur } = drumTicks(m.p, Math.abs(m.v));
    const path = Skia.Path.Make();
    for (const t of ticks) {
      path.addRect(Skia.XYWHRect(WHEEL_COLS[d] + 27, t.y - t.w / 2, t.len, t.w));
    }
    return { path, blur, a: ticks.length ? ticks[0].a : 0 };
  });
  const path = useDerivedValue(() => model.value.path);
  const blur = useDerivedValue(() => model.value.blur);
  const sharp = useDerivedValue(() => 0.25 + 0.75 * (1 - Math.min(1, model.value.blur / 2.6)));
  return (
    <Path path={path} color={WHEEL_INK_LIT} opacity={sharp}>
      <BlurMask blur={blur} style="normal" />
    </Path>
  );
}

export const WheelTimePicker = forwardRef<WheelTimePickerHandle, WheelTimePickerProps>(function WheelTimePicker(
  {
    slowMotion = false,
    reducedMotion,
    onChange,
    onFeedback,
    label = "Time picker. Three drums for hour, minute and AM or PM. Drag or fling a drum, it coasts and snaps to a row.",
    style,
  },
  ref,
) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const st = useSharedValue<WheelState>(wheelCreate());
  const frame = useSharedValue(0);
  const ptr = useSharedValue<Ptr>({ d: 0, kind: 2, dy: 0, vy: 0, seq: 0 });
  const demo = useSharedValue(0);
  const slowM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const seen = useSharedValue(0);
  const seenDemo = useSharedValue(0);
  const last = useSharedValue("");
  const latest = useRef({ onChange, onFeedback, seq: 0, demo: 0, reset: 0 });
  latest.current.onChange = onChange;
  latest.current.onFeedback = onFeedback;

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then((v) => alive && setSystemReduce(v)).catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => { slowM.value = slowMotion; }, [slowMotion, slowM]);
  useEffect(() => { reduceM.value = reduce; }, [reduce, reduceM]);

  const emit = (t: WheelTime | null, ticks: number) => {
    if (ticks > 0) latest.current.onFeedback?.("tick");
    if (t) {
      latest.current.onFeedback?.("settle");
      latest.current.onChange?.(t);
    }
  };

  const pans = useMemo(() => [0, 1, 2].map((d) => {
    const send = (kind: number, dy: number, vy: number) => {
      latest.current.seq += 1;
      ptr.value = { d, kind, dy, vy, seq: latest.current.seq };
    };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponder: () => true,
      onPanResponderGrant: () => send(0, 0, 0),
      onPanResponderMove: (_e, g) => send(1, g.dy, g.vy),
      onPanResponderRelease: (_e, g) => send(2, g.dy, g.vy),
      onPanResponderTerminate: (_e, g) => send(2, g.dy, 0),
      onPanResponderTerminationRequest: () => false,
    });
  }), [ptr]);

  useFrameCallback((info) => {
    const s = st.value;
    const p = ptr.value;
    if (p.seq !== seen.value) {
      seen.value = p.seq;
      if (p.kind === 2) wheelRelease(s, p.d, p.vy);
      else wheelGrab(s, p.d, p.dy);
    }
    if (demo.value !== seenDemo.value) {
      seenDemo.value = demo.value;
      wheelFling(s, 0, -16);
      wheelFling(s, 1, -58);
      wheelFling(s, 2, -7);
    }
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    if (reduceM.value) {
      for (let d = 0; d < 3; d++) {
        const m = s.drums[d];
        if (!m.drag && (m.v !== 0 || m.p !== Math.round(m.p))) {
          const n = WHEEL_SIZES[d];
          let r = Math.round(m.p + m.v * 0.1);
          if (d === 2) r = Math.max(0, Math.min(n - 1, r));
          m.p = r; m.v = 0; m.target = NaN; m.lastRow = r;
        }
      }
    } else {
      wheelStep(s, dt * (slowM.value ? WHEEL_SLOW : 1));
    }
    let ticks = 0;
    for (let d = 0; d < 3; d++) { ticks += s.drums[d].ticks; s.drums[d].ticks = 0; }
    let t: WheelTime | null = null;
    if (wheelSettled(s)) {
      const v = wheelValue(s);
      const key = `${v.hour}:${v.minute}:${v.period}`;
      if (key !== last.value) { last.value = key; t = v; }
    }
    if (ticks > 0 || t) runOnJS(emit)(t, ticks);
    frame.value = frame.value + 1;
  });

  useImperativeHandle(ref, () => ({
    spinDemo: () => { latest.current.demo += 1; demo.value = latest.current.demo; },
    reset: () => { st.value = wheelCreate(); last.value = ""; },
  }));

  const hourRows = useMemo(() => Array.from({ length: WHEEL_SIZES[0] }, (_, i) => i), []);
  const minRows = useMemo(() => Array.from({ length: WHEEL_SIZES[1] }, (_, i) => i), []);
  const perRows = useMemo(() => Array.from({ length: WHEEL_SIZES[2] }, (_, i) => i), []);
  const bandTop = WHEEL_CY - WHEEL_BAND_H / 2;

  return (
    <View
      style={[{ width: WHEEL_W, height: WHEEL_H, borderRadius: 26, backgroundColor: WHEEL_SHEET, borderWidth: 1, borderColor: WHEEL_SHEET_EDGE, overflow: "hidden" }, style]}
      accessibilityLabel={label}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ position: "absolute", left: -1, top: -1, width: WHEEL_W, height: WHEEL_H }}>
        <RoundedRect x={12} y={54} width={WHEEL_W - 24} height={WHEEL_H - 108} r={18}>
          <LinearGradient start={vec(0, 54)} end={vec(0, WHEEL_H - 54)} colors={[WHEEL_DRUM_TOP, WHEEL_DRUM_MID, WHEEL_DRUM_TOP]} positions={[0, 0.5, 1]} />
        </RoundedRect>
        <RoundedRect x={WHEEL_BAND_X} y={bandTop} width={WHEEL_BAND_W} height={WHEEL_BAND_H} r={12} color={WHEEL_ACCENT} opacity={0.22}>
          <BlurMask blur={14} style="normal" />
        </RoundedRect>
        <RoundedRect x={WHEEL_BAND_X} y={bandTop} width={WHEEL_BAND_W} height={WHEEL_BAND_H} r={12} color={WHEEL_BAND} />
        <RoundedRect x={WHEEL_BAND_X} y={bandTop} width={WHEEL_BAND_W} height={WHEEL_BAND_H} r={12} color={WHEEL_ACCENT} style="stroke" strokeWidth={1} opacity={0.55} />
        {[0, 1, 2].map((d) => (<Ticks key={d} st={st} frame={frame} d={d} />))}
      </Canvas>
      <Animated.Text pointerEvents="none" style={{ position: "absolute", left: 0, right: 0, top: WHEEL_TITLE_Y - 11, textAlign: "center", fontSize: 13, letterSpacing: 1.2, color: WHEEL_INK_DIM, includeFontPadding: false }}>{WHEEL_TITLE}</Animated.Text>
      {hourRows.map((i) => (<Row key={`h${i}`} st={st} frame={frame} d={0} i={i} />))}
      {minRows.map((i) => (<Row key={`m${i}`} st={st} frame={frame} d={1} i={i} />))}
      {perRows.map((i) => (<Row key={`p${i}`} st={st} frame={frame} d={2} i={i} />))}
      <Animated.Text pointerEvents="none" style={{ position: "absolute", left: WHEEL_COLON_X, top: WHEEL_CY - 22, width: 12, textAlign: "center", fontSize: WHEEL_FONT_SIZE, lineHeight: 44, color: WHEEL_ACCENT, includeFontPadding: false }}>:</Animated.Text>
      <Canvas pointerEvents="none" style={{ position: "absolute", left: -1, top: -1, width: WHEEL_W, height: WHEEL_H }}>
        <RoundedRect x={0} y={0} width={WHEEL_W} height={96}>
          <LinearGradient start={vec(0, 40)} end={vec(0, 96)} colors={[WHEEL_SHEET, "rgba(13,15,20,0)"]} />
        </RoundedRect>
        <RoundedRect x={0} y={WHEEL_H - 96} width={WHEEL_W} height={96}>
          <LinearGradient start={vec(0, WHEEL_H - 96)} end={vec(0, WHEEL_H - 40)} colors={["rgba(13,15,20,0)", WHEEL_SHEET]} />
        </RoundedRect>
      </Canvas>
      {[0, 1, 2].map((d) => (
        <View key={`g${d}`} {...pans[d].panHandlers} accessibilityLabel={["Hour", "Minute", "AM or PM"][d]} style={{ position: "absolute", left: WHEEL_COLS[d] - 48, width: 96, top: 54, height: WHEEL_H - 108 }} />
      ))}
    </View>
  );
});

// Pure motion model for the Wheel Time Picker: three drums (hour, minute,
// AM/PM) that carry real inertia and snap to a row. Every function is a
// worklet so Reanimated can step it on the UI thread; plain JS (tests, web
// preview) ignores the tag. Fixed-step integration, so native, web and tests
// agree frame for frame.
//
// Each drum is a cylinder seen from the side. A row at distance `offset`
// (rows) from the centre sits at angle offset * WHEEL_DTH, so its height is
// R sin(angle) and its text is squashed by cos(angle) - the curved-drum look.

export const WHEEL_W = 320;
export const WHEEL_H = 300;
export const WHEEL_CY = 150;
export const WHEEL_ROW_H = 40;
export const WHEEL_DTH = 0.36; // rad between rows
export const WHEEL_R = WHEEL_ROW_H / WHEEL_DTH;
export const WHEEL_COLS = [84, 170, 252];
export const WHEEL_SIZES = [12, 60, 2];
export const WHEEL_WRAP = [1, 1, 0];
export const WHEEL_SLOW = 0.25;
export const WHEEL_SETTLE = 2.2;

const FRICTION = 2.3;      // 1/s, exponential velocity decay while coasting
const SNAP_SPEED = 5;      // rows/s: below this the drum snaps to a row
const SNAP_K = 280;        // spring stiffness of the snap
const SNAP_C = 2 * Math.sqrt(SNAP_K) * 0.9;
const EDGE_K = 140;        // rubber band past the first/last row (no wrap)
const MAX_SPEED = 90;
const STEP = 1 / 240;

export function clamp01(x: number) {
  'worklet';
  return Math.max(0, Math.min(1, Number.isFinite(x) ? x : 0));
}
export function wheelMod(x: number, n: number) {
  'worklet';
  return ((x % n) + n) % n;
}

export type Drum = {
  p: number;        // position in rows (float); row index = round(p) mod n
  v: number;        // rows/s
  drag: number;     // 1 while a finger holds it
  base: number;     // p when the drag began
  target: number;   // snap target while snapping, NaN while coasting
  lastRow: number;  // last whole row, to count ticks
  ticks: number;    // rows crossed since the last read
};
export type WheelState = { drums: Drum[]; acc: number; time: number; seq: number; ticked: number };

export function wheelCreate(hour = 7, minute = 30, pm = 0): WheelState {
  'worklet';
  const start = [hour - 1, minute, pm];
  return {
    drums: start.map((p) => ({ p, v: 0, drag: 0, base: p, target: NaN, lastRow: p, ticks: 0 })),
    acc: 0, time: 0, seq: 0, ticked: 0,
  };
}

export function wheelGrab(s: WheelState, d: number, dyPx: number) {
  'worklet';
  const m = s.drums[d];
  if (!m.drag) {
    m.drag = 1;
    m.base = m.p + dyPx / WHEEL_ROW_H;
    m.target = NaN;
  }
  m.v = 0;
  const n = WHEEL_SIZES[d];
  let p = m.base - dyPx / WHEEL_ROW_H;
  if (!WHEEL_WRAP[d]) {
    // Past the ends the finger moves the drum at a third of the speed.
    if (p < 0) p = p / 3;
    if (p > n - 1) p = n - 1 + (p - (n - 1)) / 3;
  }
  m.p = p;
}

export function wheelRelease(s: WheelState, d: number, vyPxPerMs: number) {
  'worklet';
  const m = s.drums[d];
  m.drag = 0;
  const v = (-vyPxPerMs * 1000) / WHEEL_ROW_H;
  m.v = Math.max(-MAX_SPEED, Math.min(MAX_SPEED, Number.isFinite(v) ? v : 0));
  m.target = NaN;
}

/** Flick a drum as if a finger had thrown it at `v` rows/s. */
export function wheelFling(s: WheelState, d: number, v: number) {
  'worklet';
  const m = s.drums[d];
  m.drag = 0;
  m.v = v;
  m.target = NaN;
}

function stepDrum(m: Drum, d: number, h: number) {
  'worklet';
  if (m.drag) return;
  const n = WHEEL_SIZES[d];
  const wrap = WHEEL_WRAP[d] === 1;
  if (Number.isNaN(m.target)) {
    if (Math.abs(m.v) < SNAP_SPEED) {
      // Land on the row the drum was drifting toward.
      let t = Math.round(m.p + m.v * 0.1);
      if (!wrap) t = Math.max(0, Math.min(n - 1, t));
      m.target = t;
    } else {
      m.v *= Math.exp(-FRICTION * h);
    }
  }
  let a = 0;
  if (!Number.isNaN(m.target)) a = -SNAP_K * (m.p - m.target) - SNAP_C * m.v;
  else if (!wrap) {
    if (m.p < 0) a = -EDGE_K * m.p - 14 * m.v;
    else if (m.p > n - 1) a = -EDGE_K * (m.p - (n - 1)) - 14 * m.v;
  }
  m.v += a * h;
  m.p += m.v * h;
  if (!Number.isNaN(m.target) && Math.abs(m.p - m.target) < 0.0005 && Math.abs(m.v) < 0.01) {
    m.p = m.target;
    m.v = 0;
  }
  if (!wrap && !Number.isNaN(m.target)) m.target = Math.max(0, Math.min(n - 1, m.target));
}

/** Advance the whole picker by dt seconds (fixed internal step). */
export function wheelStep(s: WheelState, dt: number) {
  'worklet';
  s.acc += Math.min(dt, 0.05);
  while (s.acc >= STEP) {
    s.acc -= STEP;
    s.time += STEP;
    for (let d = 0; d < 3; d++) {
      const m = s.drums[d];
      stepDrum(m, d, STEP);
      const row = Math.round(m.p);
      if (row !== m.lastRow) {
        m.ticks += Math.abs(row - m.lastRow);
        s.ticked += Math.abs(row - m.lastRow);
        m.lastRow = row;
      }
    }
  }
}

export function wheelSettled(s: WheelState) {
  'worklet';
  for (let d = 0; d < 3; d++) {
    const m = s.drums[d];
    if (m.drag || Math.abs(m.v) > 0.01 || Math.abs(m.p - Math.round(m.p)) > 0.001) return false;
  }
  return true;
}

export function wheelValue(s: WheelState) {
  'worklet';
  return {
    hour: wheelMod(Math.round(s.drums[0].p), 12) + 1,
    minute: wheelMod(Math.round(s.drums[1].p), 60),
    period: wheelMod(Math.round(s.drums[2].p), 2) === 0 ? "AM" : "PM",
  } as { hour: number; minute: number; period: "AM" | "PM" };
}

export function rowLabel(d: number, i: number) {
  'worklet';
  if (d === 0) return String(i + 1);
  if (d === 1) return i < 10 ? `0${i}` : String(i);
  return i === 0 ? "AM" : "PM";
}

/** Signed distance in rows from the drum centre to row i. */
export function rowOffset(m: Drum, d: number, i: number) {
  'worklet';
  const n = WHEEL_SIZES[d];
  let o = i - m.p;
  if (WHEEL_WRAP[d]) o = wheelMod(o + n / 2, n) - n / 2;
  return o;
}

export type RowGeom = { y: number; s: number; a: number; blur: number; lit: number; visible: boolean };
/** Where and how one row is drawn. `speed` (rows/s) adds motion blur. */
export function rowGeom(offset: number, speed: number): RowGeom {
  'worklet';
  const th = offset * WHEEL_DTH;
  if (Math.abs(th) >= 1.45) return { y: 0, s: 0, a: 0, blur: 0, lit: 0, visible: false };
  const c = Math.cos(th);
  return {
    y: WHEEL_CY + WHEEL_R * Math.sin(th),
    s: c,
    a: Math.pow(c, 1.6),
    blur: Math.min(5, Math.abs(offset) * 1.25 + Math.min(2.2, speed * 0.03)),
    lit: clamp01(1 - Math.abs(offset) / 0.85),
    visible: true,
  };
}

/** Tick marks on a drum: half-row spacing. Sharp and bright when slow, long
 *  soft streaks when fast. */
export type Tick = { y: number; len: number; w: number; a: number };
export function drumTicks(p: number, speed: number): { ticks: Tick[]; blur: number } {
  'worklet';
  const sharp = 1 - clamp01(speed / 16);
  const out: Tick[] = [];
  const base = Math.floor(p * 2) / 2;
  for (let k = -9; k <= 9; k++) {
    const row = base + k / 2;
    const off = row - p;
    const th = off * WHEEL_DTH;
    if (Math.abs(th) >= 1.4) continue;
    const c = Math.cos(th);
    const whole = Math.abs(row - Math.round(row)) < 0.01;
    out.push({
      y: WHEEL_CY + WHEEL_R * Math.sin(th),
      len: (whole ? 7 : 4) * c * (1 + (1 - sharp) * 0.9),
      w: (whole ? 1.6 : 1.1) * (0.6 + c * 0.4),
      a: (0.18 + 0.5 * sharp) * c * (whole ? 1 : 0.7),
    });
  }
  return { ticks: out, blur: 2.6 * (1 - sharp) };
}

// Look of the Wheel Time Picker: a dark sheet with three glass drums and an
// amber selection band. Plain data shared by the Skia component and the web
// preview.
export const WHEEL_SHEET = "#0d0f14";
export const WHEEL_SHEET_EDGE = "#222630";
export const WHEEL_DRUM_TOP = "#0a0c10";
export const WHEEL_DRUM_MID = "#1c212b";
export const WHEEL_INK_LIT = "#fbf7ee";
export const WHEEL_INK_DIM = "#7b8394";
export const WHEEL_ACCENT = "#ffb43a";
export const WHEEL_BAND = "rgba(255, 180, 58, 0.10)";
export const WHEEL_TITLE = "Wake me at";
export const WHEEL_TITLE_Y = 28;
export const WHEEL_FONT_SIZE = 30;
export const WHEEL_BAND_X = 20;
export const WHEEL_BAND_W = 280;
export const WHEEL_BAND_H = 42;
export const WHEEL_COLON_X = 121;

import React, { useRef, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { WheelTimePicker, type WheelTime, type WheelTimePickerHandle } from "./WheelTimePicker";

export default function Example({ onFeedback }: { onFeedback?: (event: "tick" | "settle") => void }) {
  const ref = useRef<WheelTimePickerHandle>(null);
  const [slow, setSlow] = useState(false);
  const [time, setTime] = useState<WheelTime>({ hour: 7, minute: 30, period: "AM" });
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#1c212b" : "#eeeade", borderColor: on ? "#1c212b" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 12, paddingVertical: 14 }}>
      <WheelTimePicker ref={ref} slowMotion={slow} onFeedback={onFeedback} onChange={setTime} />
      <Text style={{ fontSize: 14, color: "#2a2f3a" }}>{time.hour}:{String(time.minute).padStart(2, "0")} {time.period}</Text>
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="button" onPress={() => ref.current?.spinDemo()} style={chip(true)}>
          <Text style={{ fontSize: 12, color: "#fff" }}>Spin for me</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#2a2f3a" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f" }}>Drag or fling a drum. It coasts and snaps to a row.</Text>
    </View>
  );
}
